import sys, json, time, math
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
OUT=Path('/app/output'); RUN=Path('/app/runs'); RUN.mkdir(exist_ok=True)
class Painter:
 def __init__(self):
  self.r=Robot(); self.spec=self.r.spec(); o=self.r.get_obs(cameras=[])
  self.p=np.array(o.meta['proprio']['now'][7:14]);self.q=np.array([0.,1.,0.,0.]);self.buf=[];self.color=None
  self.logfile=OUT/'actions.jsonl'; self.callnum=int(o.meta['calls'])
 def move(self,xyz,speed=.12,hold=0):
  dest=np.r_[xyz,self.q]; n=max(1,int(np.ceil(np.linalg.norm(dest[:3]-self.p[:3])/speed/.05)))
  self.buf.extend(np.linspace(self.p,dest,n+1)[1:].tolist());self.buf.extend([dest.tolist()]*int(round(hold/.05)));self.p=dest
 def flush(self,cams=[],frames=False):
  results=[]
  while self.buf:
   a=self.buf[:190]; del self.buf[:190]
   before=self.r.status()
   try: res=self.r.submit('ee_pose',a,dt=.05,cameras=cams,video='frames' if frames else 'none',video_fps=20,note='single-sweep brush painting')
   except Exception:
    stat=self.r.wait_ready();print('RECOVERY',stat,flush=True)
    if stat['control_steps']==before['control_steps']:res=self.r.submit('ee_pose',a,dt=.05,cameras=cams,video='none')
    else:raise RuntimeError('Ambiguous call completion; inspect log before continuing')
   self.callnum=res.meta['calls']
   with self.logfile.open('a') as f:f.write(json.dumps({'call':self.callnum,'a':a,'control_steps':res.meta['control_steps'],'plan':res.meta.get('plan')})+'\n')
   fails=sum(t.get('ik_failures',0) for t in res.meta.get('plan',[]))
   if fails or res.stopped or res.done:print('PLAN WARNING',fails,res.meta,flush=True);raise RuntimeError('motion incomplete')
   if frames:res.save(str(RUN/f'cal_{self.callnum:04d}'))
   results.append(res)
  return results
 def dip(self,c):
  # Well centers recovered from scene RGB and aligned depth.
  row=c//6;col=c%6
  x=-.155+col*.022;y=.137+row*.022
  self.move([self.p[0],self.p[1],.065],hold=.1)
  self.move([x,y,.065],speed=.18,hold=.15)
  self.move([x,y,.024],speed=.07,hold=.3)
  self.move([x,y,.065],speed=.07,hold=.15);self.color=c
 def sweep_world(self,pts,depth,speed=.04):
  pts=np.array(pts);z=.0202-depth
  self.move([self.p[0],self.p[1],.050],speed=.12,hold=.1)
  self.move([*pts[0],.050],speed=.18,hold=.15)
  self.move([*pts[0],z],speed=.055,hold=.2)
  for pt in pts[1:]:self.move([*pt,z],speed=speed)
  self.move([*pts[-1],z],hold=.15)
  self.move([*pts[-1],.050],speed=.055,hold=.15)
 def sweep(self,pts,width,c):
  if self.color!=c:self.dip(c)
  # Target picture coordinates, millimetres.
  pts=np.array(pts);world=np.column_stack((.0135925-pts[:,1]/1000,.1135925-pts[:,0]/1000))
  self.sweep_world(world,depth_for_width(width))
