  A+=a*a;
  for(int k=0;k<3;k++){float cur=C[i+k],tar=T[i+k];V[k]+=a*tar-a*(1-a)*cur;K+=2*a*(cur-tar)*cur-a*a*cur*cur;}
 }
 if(draw)return s;
 s.gain=-1e30;s.col=0;
 for(int c=0;c<16;c++){float g=K;for(int k=0;k<3;k++)g+=2*P[c*3+k]*V[k]-A*P[c*3+k]*P[c*3+k];if(g>s.gain){s.gain=g;s.col=c;}}
 return s;
}
extern "C" void optimize(int n,float *target,float *canvas,float *pal,int count,float *out,int seed,int candidates,float minwmm,float maxwmm){
 N=n;T=target;C=canvas;P=pal;scale=N/227.185f;rng.seed(seed);float minw=minwmm*scale,maxw=maxwmm*scale;
 for(int iter=0;iter<count;iter++){
  std::vector<double> weights(N*N);double acc=0;for(int i=0;i<N*N;i++){float e=0;for(int k=0;k<3;k++)e+=pow(C[i*3+k]-T[i*3+k],2);acc+=pow(e+3,1.2);weights[i]=acc;}
  std::vector<Stroke> best;
  for(int j=0;j<candidates;j++){
   int p=std::lower_bound(weights.begin(),weights.end(),rnd()*acc)-weights.begin();p=std::min(N*N-1,p);
   Stroke s; s.x=p%N;s.y=p/N;s.w=minw+pow(rnd(),.65f)*(maxw-minw);s.ang=rnd()*M_PI;
   s.len=(2+pow(rnd(),1.8)*65)*scale;
   // Test a mixture of long structural sweeps and short petal marks.
   if(rnd()<.35)s.len=(2+rnd()*16)*scale;
